import{d as e,k as t,m as n,t as r}from"./chunks/plugin-vue_export-helper.sM-KdTqA.js";const i=JSON.parse(`{"title":"AI 智能助手与全栈生成","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/ai-assistant.md","filePath":"zh/guide/ai-assistant.md"}`);var a={name:`zh/guide/ai-assistant.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h1 id="ai-智能助手与全栈生成" tabindex="-1">AI 智能助手与全栈生成 <a class="header-anchor" href="#ai-智能助手与全栈生成" aria-label="Permalink to “AI 智能助手与全栈生成”">​</a></h1><p>QC Flutter Flow 内置了深度理解画布组件、中文 DSL 与后端接口的 <strong>AI 全栈智能助手</strong>。无论是从零搭建一整套带后端数据库的应用，还是对当前画布上的某个按钮、卡片做样式微调，你都可以直接通过自然语言对话完成。</p><hr><h2 id="一、打开-ai-助手与配置模型" tabindex="-1">一、打开 AI 助手与配置模型 <a class="header-anchor" href="#一、打开-ai-助手与配置模型" aria-label="Permalink to “一、打开 AI 助手与配置模型”">​</a></h2><ol><li>在画布编辑器右侧面板顶部，点击切换到 <strong>「🤖 AI 助手」</strong> 标签页（或在主控台点击「AI 工作台」）。</li><li>点击面板右上角的 <strong>「模型设置」</strong> 图标，可选择并配置你常用的 AI 模型与 API Key，支持一键测试连通性。</li><li>在底部输入框中，你不仅可以直接输入文字需求，还可以点击附件栏关联特定的页面或上下文。</li></ol><hr><h2 id="二、三大高频使用场景" tabindex="-1">二、三大高频使用场景 <a class="header-anchor" href="#二、三大高频使用场景" aria-label="Permalink to “二、三大高频使用场景”">​</a></h2><p>平台内置了<strong>智能意图识别分流引擎</strong>，会根据你的提问内容自动判断应该走「全栈创建通道」还是「秒级局部修改快车道」：</p><h3 id="场景-1-从零生成多页面全栈应用-前端界面-后端服务" tabindex="-1">场景 1：从零生成多页面全栈应用（前端界面 + 后端服务） <a class="header-anchor" href="#场景-1-从零生成多页面全栈应用-前端界面-后端服务" aria-label="Permalink to “场景 1：从零生成多页面全栈应用（前端界面 + 后端服务）”">​</a></h3><p>当你想要快速搭建一个完整业务系统时，直接描述你的业务场景与包含的页面：</p><blockquote><p><strong>提问示例</strong>： “帮我做一个宠物领养系统，包含首页（展示待领养宠物数据统计卡片、分类筛选和宠物列表）、宠物详情页和领养申请页，并生成配套的后端接口和初始测试数据。”</p></blockquote><p><strong>执行流程</strong>：</p><ol><li><strong>生成规划卡片（Plan Approval）</strong>：AI 会先梳理出详细的实施路线图（包含要创建的页面、组件结构、后端数据库表与 API 接口契约），展示在聊天面板中供你审阅。</li><li><strong>前后端协同生成</strong>：点击确认后，全栈助手会自动： <ul><li>生成后端服务代码与初始测试数据；</li><li>自动分配不冲突的本地端口并启动后端守护进程；</li><li>将后端端口自动同步到项目的「API 接口中枢」；</li><li>生成所有前端画布页面、状态变量与接口调用代码，并将数据字段自动绑定到列表和文本组件上。</li></ul></li><li><strong>一键真机验证</strong>：生成完成后，直接点击顶部「运行」，页面即可直接显示来自真实后端的接口数据！</li></ol><hr><h3 id="场景-2-画布-ui-局部微调-极速快车道" tabindex="-1">场景 2：画布 UI 局部微调（极速快车道） <a class="header-anchor" href="#场景-2-画布-ui-局部微调-极速快车道" aria-label="Permalink to “场景 2：画布 UI 局部微调（极速快车道）”">​</a></h3><p>当你的应用已经生成好，只想调整某个页面的局部外观或排版时，直接告诉 AI：</p><blockquote><p><strong>提问示例</strong>：</p><ul><li>“把首页顶部的统计卡片改成浅蓝色渐变背景，圆角调成 16。”</li><li>“UI 有一些问题，帮我把列表卡片里的间距调大一点，价格标签改成红色。”</li><li>“在搜索框右边加一个筛选图标按钮。”</li></ul></blockquote><p><strong>为什么局部微调特别快？</strong> 当 AI 识别到你的需求属于 <strong>UI 调整</strong> 时，会自动进入 <strong>L1 极速修改快车道</strong>——只针对当前画布节点树进行精准增删改，<strong>绝对不会重新生成或重启你的后端服务</strong>，修改在几秒钟内即可直接呈现在画布上。</p><hr><h3 id="场景-3-页面报错与逻辑问题一键修复" tabindex="-1">场景 3：页面报错与逻辑问题一键修复 <a class="header-anchor" href="#场景-3-页面报错与逻辑问题一键修复" aria-label="Permalink to “场景 3：页面报错与逻辑问题一键修复”">​</a></h3><p>如果你在底部「诊断面板」看到 DSL 语法报错，或者某个按钮点击后的逻辑不对：</p><blockquote><p><strong>提问示例</strong>：</p><ul><li>“帮我修复一下当前页面的语法报错。”</li><li>“点击提交按钮时，加上手机号不能为空的校验提示。”</li></ul></blockquote><p>AI 会直接读取当前页面的诊断信息与代码，精准修复对应的事件函数，同样走极速通道，不会影响项目的其它页面与后端数据。</p><hr><h2 id="三、全栈协同抽屉与后端状态监控" tabindex="-1">三、全栈协同抽屉与后端状态监控 <a class="header-anchor" href="#三、全栈协同抽屉与后端状态监控" aria-label="Permalink to “三、全栈协同抽屉与后端状态监控”">​</a></h2><p>当你的项目启用了全栈后端服务时，可以在画布右上角或侧边打开 <strong>「全栈协同面板 (Fullstack Co-Dev)」</strong>：</p><ul><li><strong>实时状态指示灯</strong>：直观查看本地后端服务当前是否在线运行、监听的端口号（如 <code>Port: 18432</code>）以及 <code>/health</code> 健康检查状态。</li><li><strong>一键重启与切换保护</strong>：支持手动重启后端服务、查看后端实时请求日志；在切换不同项目时，系统具备端口隔离与安全守护提示，防止多个项目的后端服务互相串扰。</li></ul><hr><h2 id="四、审阅-ai-修改与安全回滚" tabindex="-1">四、审阅 AI 修改与安全回滚 <a class="header-anchor" href="#四、审阅-ai-修改与安全回滚" aria-label="Permalink to “四、审阅 AI 修改与安全回滚”">​</a></h2><ul><li>每次 AI 对画布或代码完成修改后，聊天流中都会生成一张 <strong>「修改审阅卡片」</strong>，清晰列出本次新增、修改了哪些组件与函数。</li><li>如果你对某次 AI 调整的效果不满意，只需按下快捷键 <code>Ctrl + Z</code>（macOS 为 <code>Cmd + Z</code>）或点击顶部工具栏的 <strong>「撤销」</strong> 按钮，即可一键无损回退到修改前的状态。</li></ul>`,30)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};